def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A sequence is any contiguous nonzero run in an outer row.
    sequences = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            sequences.append((r, start, grid[r][start:c]))

    # Each isolated colored cell indicates where to place its matching sequence.
    for r in range(1, h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            if any(0 <= r + dr < h and 0 <= c + dc < w and
                   grid[r + dr][c + dc] != 0
                   for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))):
                continue

            matches = [seq for _, _, seq in sequences if color in seq]
            if not matches:
                continue
            # In case of a shared color, prefer the sequence with the closest
            # corresponding occurrence in its exemplar row.
            seq = min(matches, key=lambda s: abs(s.index(color) - c))
            start = c - seq.index(color)
            for i, value in enumerate(seq):
                x = start + i
                if 0 <= x < w:
                    out[r][x] = value
    return out
